+)
+
+type testTx struct {
+	id ids.ID
+}
+
+func (t *testTx) GetID() ids.ID {
+	return t.id
+}
+
+func (t *testTx) Marshal() ([]byte, error) {
+	return t.id[:], nil
+}
+
+func (t *testTx) Unmarshal(bytes []byte) error {
+	t.id = ids.ID{}
+	copy(t.id[:], bytes)
+	return nil
+}
+
+type testSet struct {
+	set   set.Set[*testTx]
+	bloom *BloomFilter
+	onAdd func(tx *testTx)
+}
