+		t.onAdd(gossipable)
+	}
+
+	return nil
+}
+
+func (t testSet) Iterate(f func(gossipable *testTx) bool) {
+	for tx := range t.set {
+		if !f(tx) {
+			return
+		}
+	}
+}
+
+func (t testSet) GetFilter() ([]byte, []byte, error) {
+	bloom, err := t.bloom.Bloom.MarshalBinary()
+	return bloom, t.bloom.Salt[:], err
+}
